/*
 * Accent presets, switched at runtime with data-accent on <html> (no attribute = blue).
 * The attribute also works on any element to give one section its own accent.
 * Generated by tooling/scripts/gen-theme.py from the theme-<name> registry items; import after the theme.
 */

html[data-accent="neutral"],
[data-accent="neutral"] {
  --primary: #000000f2;
  --primary-hover: #000000cc;
  --primary-active: #000000b2;
  --primary-foreground: #fff;
  --primary-subtle: #0000000f;
  --primary-subtle-hover: #00000017;
  --primary-border: #00000026;
  --primary-text: #000000df;
  --ring: #00000070;
  --selection: #00000029;
}

html[data-accent="neutral"].dark,
.dark [data-accent="neutral"] {
  --primary: #fffffff2;
  --primary-hover: #ffffffcc;
  --primary-active: #ffffffb2;
  --primary-foreground: #000;
  --primary-subtle: #ffffff12;
  --primary-subtle-hover: #ffffff1b;
  --primary-border: #ffffff2b;
  --primary-text: #ffffffed;
  --ring: #ffffff5c;
  --selection: #ffffff3d;
}

html[data-accent="blue"],
[data-accent="blue"] {
  --primary: oklch(56% 0.1671 251.78);
  --primary-hover: oklch(52.5% 0.1568 251.78);
  --primary-active: oklch(49% 0.1465 251.78);
